/**
 * The dot field's drawing, kept out of the component so it can be checked
 * without a renderer — the same split `progress-button-hold` uses.
 *
 * ## Nothing is built while it is running
 *
 * The field is hundreds of dots and it is on screen for as long as a model
 * takes to answer, on a page that may be showing several at once. So every
 * frame it will ever draw is built when the box is measured, and playing it is
 * handing react-native-svg a string that already exists.
 *
 * Two earlier versions did this the obvious ways and both stalled a page of
 * them on scroll: one rebuilt every dot as a path string on every frame, the
 * other clipped a moving shape of light to a path with hundreds of subpaths in
 * it, which is re-rasterized every time the view is drawn.
 */

/** Points between one dot and the next. */
export const DOT_GAP = 10;

/** The dot's radius where the light is not, and where it is strongest. */
export const DOT_RADIUS = 1;
export const DOT_LIT_RADIUS = 1.9;

/** How visible the resting grid is, under everything. */
export const DOT_REST_OPACITY = 0.16;

/** How many still frames one loop is drawn as. */
export const FRAMES = 24;

/**
 * The most dots the field will draw, whatever box it is given.
 *
 * The grid opens up rather than the count running away: a full-width field on
 * a tablet gets the same picture drawn coarser, which costs the same and looks
 * the same at arm's length.
 */
const MAX_DOTS = 700;

/** How the light moves through the field. */
export type DotFieldAnimation = 'drift' | 'pulse' | 'scan';

/** The gap this box is drawn at, opened up if the grid would be too dense. */
export function gapFor(width: number, height: number): number {
  if (width <= 0 || height <= 0) return DOT_GAP;
  const cells = (width / DOT_GAP + 1) * (height / DOT_GAP + 1);
  return cells > MAX_DOTS ? DOT_GAP * Math.sqrt(cells / MAX_DOTS) : DOT_GAP;
}

/** A circle as an SVG subpath, which is two half arcs. */
function circle(x: number, y: number, r: number): string {
  const d = (r * 2).toFixed(2);
  return `M${(x - r).toFixed(2)},${y.toFixed(2)}a${r},${r} 0 1,0 ${d},0a${r},${r} 0 1,0 -${d},0`;
}

/**
 * Every dot's anchor, in reading order.
 *
 * Laid out inside the box by the widest a dot can be drawn, and counted with
 * `floor` rather than `ceil`, so no part of any dot falls outside it.
 *
 * Counted with `ceil` the grid overhangs by up to half a gap on every side.
 * That is invisible while the light stays near the middle and obvious the
 * moment it reaches an edge — which the scanning band does by design, and a
 * short wide box does simply by being short. The dots then draw outside the
 * card, which looks like the animation has escaped it.
 *
 * The row and column are still centred in whatever is left over, because laid
 * out from the origin the field ends with a strip of nothing down one edge.
 */
function anchors(width: number, height: number): [number, number][] {
  const gap = gapFor(width, height);
  const margin = DOT_LIT_RADIUS;
  const innerWidth = Math.max(0, width - margin * 2);
  const innerHeight = Math.max(0, height - margin * 2);

  const columns = Math.floor(innerWidth / gap) + 1;
  const rows = Math.floor(innerHeight / gap) + 1;
  const offsetX = margin + (innerWidth - (columns - 1) * gap) / 2;
  const offsetY = margin + (innerHeight - (rows - 1) * gap) / 2;

  const out: [number, number][] = [];
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      out.push([offsetX + column * gap, offsetY + row * gap]);
    }
  }
  return out;
}

/** The resting grid as one path. Drawn once, under the light. */
export function gridPath(width: number, height: number): string {
  if (width <= 0 || height <= 0) return '';
  let path = '';
  for (const [x, y] of anchors(width, height)) path += circle(x, y, DOT_RADIUS);
  return path;
}

/** How many dots {@link gridPath} would draw for a box. */
export function dotCount(width: number, height: number): number {
  if (width <= 0 || height <= 0) return 0;
  return anchors(width, height).length;
}

/**
 * How strongly a dot at `distance` from the light is lit.
 *
 * Smoothstep rather than a linear ramp: linear gives the light a hard rim,
 * because the eye finds the discontinuity in the first derivative. This one
 * arrives and leaves at zero slope, so the light has no edge.
 */
export function influenceAt(distance: number, radius: number): number {
  if (radius <= 0) return 0;
  const proximity = Math.max(0, 1 - distance / radius);
  return proximity * proximity * (3 - 2 * proximity);
}

/**
 * Where the light is at a phase of the loop, and how wide it reaches.
 *
 * `drift` wanders around the middle — two periods that do not divide into each
 * other, so the path never closes into a loop the eye can learn, and small
 * amplitudes because a light that reaches the corners stops reading as one
 * source. `pulse` is a ring leaving the centre. `scan` crosses as a band, which
 * is the same maths with the light infinitely tall.
 */
function lightAt(
  animation: DotFieldAnimation,
  phase: number,
  width: number,
  height: number
): { x: number; y: number; radius: number; ring: number } {
  const short = Math.min(width, height);
  const turn = phase * Math.PI * 2;

  if (animation === 'pulse') {
    const reach = Math.sqrt(width * width + height * height) / 2;
    return { x: width / 2, y: height / 2, radius: short * 0.3, ring: phase * reach };
  }

  if (animation === 'scan') {
    // A band: infinitely tall, so only the horizontal distance counts.
    //
    // It starts and ends half a band clear of the edges rather than a whole
    // one — far enough to ramp in and out, near enough that some of it is
    // always on the field. Travelling fully off, the loop spends several
    // frames drawing nothing at all, which reads as the component having
    // stopped rather than as a band that has passed.
    const radius = width * 0.28;
    return {
      x: -radius * 0.5 + phase * (width + radius),
      y: Number.NaN,
      radius,
      ring: 0,
    };
  }

  return {
    x: width / 2 + Math.sin(turn) * width * 0.26,
    y: height / 2 + Math.cos(turn * 1.37) * height * 0.22,
    radius: short * 0.42,
    ring: 0,
  };
}

/**
 * The lit dots at one phase of the loop, as a path.
 *
 * Only the dots the light actually reaches are in it — the rest are already
 * drawn by the resting grid underneath, so this is a fraction of the field
 * rather than all of it.
 */
export function litPath(
  width: number,
  height: number,
  phase: number,
  animation: DotFieldAnimation = 'drift'
): string {
  if (width <= 0 || height <= 0) return '';

  const light = lightAt(animation, phase, width, height);
  let path = '';

  for (const [x, y] of anchors(width, height)) {
    const deltaX = x - light.x;
    const deltaY = Number.isNaN(light.y) ? 0 : y - light.y;
    const distance = Math.abs(
      Math.sqrt(deltaX * deltaX + deltaY * deltaY) - light.ring
    );
    const influence = influenceAt(distance, light.radius);
    if (influence <= 0.02) continue;
    path += circle(x, y, DOT_RADIUS + influence * (DOT_LIT_RADIUS - DOT_RADIUS));
  }

  return path;
}

/**
 * Every frame of the loop, built once.
 *
 * A still frame the light is somewhere legible in is also what a paused or
 * reduced-motion field shows, so there is no separate code path for holding it.
 */
export function litFrames(
  width: number,
  height: number,
  animation: DotFieldAnimation = 'drift'
): string[] {
  return Array.from({ length: FRAMES }, (_unused, index) =>
    litPath(width, height, index / FRAMES, animation)
  );
}

/** One pass of the loop, in milliseconds, per animation. */
export const PERIOD: Record<DotFieldAnimation, number> = {
  drift: 4200,
  pulse: 2200,
  scan: 1900,
};

/** Which frame a moment falls on. */
export function frameAt(time: number, animation: DotFieldAnimation): number {
  'worklet';
  const phase = (time % PERIOD[animation]) / PERIOD[animation];
  return Math.min(FRAMES - 1, Math.floor(phase * FRAMES));
}

/**
 * ImageGeneration — the place an image will be, while it is being made.
 *
 * ```tsx
 * <ImageGeneration status={status} prompt="a quiet mountain at sunset">
 *   <Image source={{ uri }} />
 * </ImageGeneration>
 * ```
 *
 * A generated image arrives seconds after it is asked for, and arrives at a
 * size nobody knew in advance. Left to itself that is a screen that reflows
 * under the reader's thumb at the moment they were about to tap something —
 * so this reserves the box first, at the aspect ratio the image will have, and
 * fills it with something to watch.
 *
 * ## The dot field
 *
 * A grid of dots with a soft band of light travelling across it. Each column
 * is one animated view holding its own dots, so a field of five hundred dots
 * costs twenty-two worklets a frame rather than five hundred — the dots inside
 * a column never move independently of it, and at this scale nobody can tell.
 *
 * The per-dot brightness underneath the band is fixed, and comes from the
 * dot's own coordinates. Without it the field reads as clean vertical stripes
 * sweeping past; with it, it reads as the individual dots lighting up.
 *
 * ## What arrives, and when
 *
 * `status` moves the picture through the work rather than switching it: the
 * field fades as the image fades in, and for one step in the middle both are
 * visible at once. That overlap is the point — an image that appears the
 * instant the field vanishes has been swapped in, and one that surfaces
 * through it has been developed.
 *
 * ## Reduced motion
 *
 * The band stops, and the field is drawn at one still frame of itself. A
 * placeholder that shows nothing is indistinguishable from a component that
 * failed to load, so this is a quieter picture rather than an empty one.
 */
import { useEffect, useId, useMemo, useState, type ReactNode } from 'react';
import {
  Pressable,
  StyleSheet,
  View,
  type LayoutChangeEvent,
  type ViewProps,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import Animated, {
  Easing,
  cancelAnimation,
  useAnimatedProps,
  useAnimatedStyle,
  useFrameCallback,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withTiming,
  type SharedValue,
} from 'react-native-reanimated';
import { tv } from 'tailwind-variants';
import { useCSSVariable } from 'uniwind';
import { useDirectionSign } from '@/hooks/use-direction';
import { AlertTriangleIcon, CheckIcon, RotateCcwIcon } from '@/components/ui/icons';
import { Text } from '@/components/ui/text';
import { cn } from '@/lib/cn';
import {
  DOT_REST_OPACITY,
  frameAt,
  gridPath,
  litFrames,
  type DotFieldAnimation,
} from '@/components/ui/dot-field';

/** How far the generation has got. */
export type ImageGenerationStatus =
  | 'queued'
  | 'generating'
  | 'refining'
  | 'complete'
  | 'error';

/**
 * The moment a held field is frozen at.
 *
 * Not zero: at zero the light sits dead centre, which reads as a target rather
 * than as something passing through.
 */
const STILL_FRAME = 900;

/** How visible the field is at each step of the work. */
const FIELD_OPACITY: Record<ImageGenerationStatus, number> = {
  queued: 1,
  generating: 1,
  refining: 0.48,
  complete: 0,
  error: 0,
};

/**
 * How visible the image is at each step.
 *
 * `refining` is the overlap: the field is still there at half strength and the
 * image is already coming through it. Both fully on for one step is what makes
 * the picture surface rather than get swapped in.
 */
const MEDIA_OPACITY: Record<ImageGenerationStatus, number> = {
  queued: 0,
  generating: 0,
  refining: 0.62,
  complete: 1,
  error: 0.28,
};

/**
 * How much larger than final the image starts.
 *
 * Small, and it settles rather than zooms. A generated image is not arriving
 * from anywhere; the scale is there to give the last of the fade somewhere to
 * go, so it does not simply stop.
 */
const MEDIA_SCALE: Record<ImageGenerationStatus, number> = {
  queued: 1.02,
  generating: 1.02,
  refining: 1.008,
  complete: 1,
  error: 1,
};

const STATUS_TEXT: Record<ImageGenerationStatus, string> = {
  queued: 'Waiting to generate',
  generating: 'Creating image',
  refining: 'Refining details',
  complete: 'Image ready',
  error: 'Generation failed',
};

const imageGenerationVariants = tv({
  slots: {
    root: 'w-full',
    frame: 'relative w-full overflow-hidden rounded-2xl bg-muted',
    media: 'absolute inset-0',
    resolution:
      'absolute end-2 top-2 rounded-full bg-background/75 px-2 py-0.5 text-[10px] text-muted-foreground',
    status: 'mt-3 flex-row items-center gap-2',
    statusText: 'text-sm font-medium text-foreground',
    prompt: 'mt-0.5 text-xs text-muted-foreground',
    retry: 'mt-3 min-h-12 flex-row items-center gap-2 self-start rounded-full px-3 active:bg-accent',
    retryLabel: 'text-sm font-medium text-foreground',
  },
  variants: {
    size: {
      /** Held to a thumbnail, centred — a result inside a conversation. */
      compact: { root: 'max-w-52 self-center' },
      /** As wide as it is given. */
      fluid: {},
    },
    error: {
      true: { statusText: 'text-destructive' },
    },
  },
  defaultVariants: {
    size: 'compact',
  },
});

const AnimatedPath = Animated.createAnimatedComponent(Path);

export interface ImageGenerationFieldProps extends Omit<ViewProps, 'children'> {
  className?: string;
  /** Holds the light still, at one representative frame. */
  paused?: boolean;
  /**
   * How the light moves through the field.
   *
   * `drift` wanders around the middle; `pulse` is a ring leaving the centre;
   * `scan` crosses as a band. All three cost the same.
   */
  animation?: DotFieldAnimation;
}

/**
 * The dot field on its own, for a placeholder that is not an image.
 *
 * It fills its parent absolutely rather than sizing to its contents, because
 * what it draws has no intrinsic height — laid out normally it measures to
 * nothing and draws a single row of dots along the top.
 *
 * ## What it costs
 *
 * Two paths: the resting grid, and the lit dots over it. Both are built when
 * the box is measured — every frame of the loop at once — so running it is
 * handing over a string that already exists, and a page of these costs the
 * same as a page of static drawings plus one property assignment each.
 */
function ImageGenerationField({
  className,
  paused = false,
  animation = 'drift',
  style,
  ...props
}: ImageGenerationFieldProps) {
  const reducedMotion = useReducedMotion();
  const [size, setSize] = useState({ width: 0, height: 0 });
  const clock = useSharedValue(STILL_FRAME);

  const tint = useCSSVariable('--color-muted-foreground');
  const color = typeof tint === 'string' ? tint : '#737373';

  const running = !paused && !reducedMotion;

  const grid = useMemo(
    () => gridPath(size.width, size.height),
    [size.width, size.height]
  );
  const frames = useMemo(
    () => litFrames(size.width, size.height, animation),
    [animation, size.width, size.height]
  );

  const frame = useFrameCallback((info) => {
    'worklet';
    // Accumulated rather than read off the total, so pausing and resuming does
    // not jump the light to wherever the clock would have carried it. A dropped
    // frame is clamped: a 300ms hitch played back whole is a lurch.
    clock.value += Math.min(info.timeSincePreviousFrame ?? 16, 48);
  }, false);

  const { setActive } = frame;
  useEffect(() => {
    setActive(running);
    return () => setActive(false);
  }, [running, setActive]);

  /*
   * A still field is not an empty one.
   *
   * Held and reduced-motion fields keep whichever frame the clock is on, and
   * the clock starts partway through the loop rather than at zero — so the
   * light is somewhere legible rather than dead centre or absent, which is the
   * difference between "not animating" and "failed to load".
   */
  const animatedProps = useAnimatedProps(() => ({
    d: frames[frameAt(clock.value, animation)] ?? '',
  }));

  const onLayout = (event: LayoutChangeEvent) => {
    const { width, height } = event.nativeEvent.layout;
    setSize((was) => (was.width === width && was.height === height ? was : { width, height }));
  };

  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      pointerEvents="none"
      onLayout={onLayout}
      className={className}
      style={[StyleSheet.absoluteFill, style]}
      {...props}
    >
      {grid ? (
        <Svg width={size.width} height={size.height}>
          {/* The field at rest, under everything and never touched again. */}
          <Path d={grid} fill={color} fillOpacity={DOT_REST_OPACITY} />
          {/* The dots the light has reached, drawn larger over their own
              resting copies rather than instead of them — so a dot brightens
              in place instead of appearing to move. */}
          <AnimatedPath animatedProps={animatedProps} fill={color} fillOpacity={0.9} />
        </Svg>
      ) : null}
    </View>
  );
}

export interface ImageGenerationProps extends Omit<ViewProps, 'children'> {
  className?: string;
  /** How far the generation has got. Defaults to `generating`. */
  status?: ImageGenerationStatus;
  /**
   * What the box is, for a screen reader. Defaults to the status text, with
   * the prompt after it where there is one.
   */
  label?: string;
  /** The instruction the image was made from. Shown under the status. */
  prompt?: string;
  /** Shown in the corner of the frame. Pass an empty string to drop it. */
  resolution?: string;
  /**
   * The box's shape, as width over height. Defaults to `1` — square, which is
   * what most models return, and what the frame must be before there is an
   * image to measure.
   */
  aspectRatio?: number;
  /** `compact` caps the width at a thumbnail and centres it; `fluid` fills. */
  size?: 'compact' | 'fluid';
  /**
   * How the light behind the dots moves while there is work outstanding.
   * `drift` wanders, `pulse` leaves the centre as a ring, `scan` crosses as a
   * band. All three cost the same.
   */
  animation?: DotFieldAnimation;
  /** Replaces the sentence under the frame. */
  statusText?: string;
  /** Hides the status line, leaving the frame and the prompt. */
  showStatus?: boolean;
  /** Shown as a button under an `error`. Without it there is no button. */
  onRetry?: () => void;
  /** Extra classes for the frame — its radius, ground and aspect. */
  frameClassName?: string;
  /** Extra classes for the layer the image sits in. */
  mediaClassName?: string;
  /** Extra classes for the status line. */
  statusClassName?: string;
  /** The finished image. Anything that fills its parent — an `Image`, a video. */
  children?: ReactNode;
}

/** The mark beside the status: a turning square while it works, then an answer. */
function StatusMark({ status }: { status: ImageGenerationStatus }) {
  const reducedMotion = useReducedMotion();
  const spin = useSharedValue(0);
  const working = status !== 'complete' && status !== 'error';

  useEffect(() => {
    if (!working || reducedMotion) {
      cancelAnimation(spin);
      spin.value = 0;
      return;
    }
    spin.value = 0;
    spin.value = withRepeat(
      withTiming(1, { duration: 2400, easing: Easing.inOut(Easing.quad) }),
      -1
    );
    return () => cancelAnimation(spin);
  }, [reducedMotion, spin, working]);

  const style = useAnimatedStyle(() => ({
    transform: [{ rotate: `${spin.value * 360}deg` }],
  }));

  const tint = useCSSVariable('--color-muted-foreground');
  const color = typeof tint === 'string' ? tint : '#737373';

  if (status === 'complete') return <CheckIcon size={14} />;
  if (status === 'error') return <AlertTriangleIcon size={14} />;

  // Four dots turning as a block: the same shape as the field it stands for,
  // small enough to sit on a line of text.
  return (
    <Animated.View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={[{ width: 14, height: 14, flexDirection: 'row', flexWrap: 'wrap', gap: 2 }, style]}
    >
      {[1, 0.55, 0.55, 1].map((opacity, index) => (
        <View
          key={index}
          style={{ width: 5, height: 5, borderRadius: 1, backgroundColor: color, opacity }}
        />
      ))}
    </Animated.View>
  );
}

function ImageGenerationRoot({
  className,
  status = 'generating',
  label,
  prompt,
  resolution = '1024 × 1024',
  aspectRatio = 1,
  size = 'compact',
  animation = 'drift',
  statusText,
  showStatus = true,
  onRetry,
  frameClassName,
  mediaClassName,
  statusClassName,
  children,
  ...props
}: ImageGenerationProps) {
  const reducedMotion = useReducedMotion();
  const working = status === 'queued' || status === 'generating' || status === 'refining';
  const slots = imageGenerationVariants({ size, error: status === 'error' });
  const sentence = statusText ?? STATUS_TEXT[status];

  const progress = useSharedValue(MEDIA_OPACITY[status]);
  const fieldFade = useSharedValue(FIELD_OPACITY[status]);
  const scale = useSharedValue(MEDIA_SCALE[status]);

  useEffect(() => {
    const duration = reducedMotion ? 0 : 400;
    progress.value = withTiming(MEDIA_OPACITY[status], { duration });
    fieldFade.value = withTiming(FIELD_OPACITY[status], { duration });
    scale.value = withTiming(MEDIA_SCALE[status], { duration });
  }, [fieldFade, progress, reducedMotion, scale, status]);

  useEffect(
    () => () => {
      cancelAnimation(progress);
      cancelAnimation(fieldFade);
      cancelAnimation(scale);
    },
    [fieldFade, progress, scale]
  );

  const mediaStyle = useAnimatedStyle(() => ({
    opacity: progress.value,
    transform: [{ scale: scale.value }],
  }));
  const fieldStyle = useAnimatedStyle(() => ({ opacity: fieldFade.value }));

  return (
    <View {...props} className={slots.root({ className })}>
      <View
        accessible
        accessibilityRole="image"
        accessibilityLabel={label ?? (prompt ? `${sentence}: ${prompt}` : sentence)}
        // `busy` is what tells a screen reader the box is not the answer yet.
        accessibilityState={{ busy: working }}
        style={{ aspectRatio }}
        className={slots.frame({ className: frameClassName })}
      >
        <Animated.View
          className={cn(slots.media(), mediaClassName)}
          style={mediaStyle}
          // Nothing to announce until there is something in it.
          accessibilityElementsHidden={working}
          importantForAccessibility={working ? 'no-hide-descendants' : 'auto'}
        >
          {children}
        </Animated.View>

        {/* Kept mounted at zero rather than unmounted, so the image is not
            fading in over a box that is simultaneously being torn down. The
            field stops drawing as soon as there is no work left, so an idle
            one costs nothing but the views. */}
        <Animated.View
          style={[StyleSheet.absoluteFill, fieldStyle]}
          pointerEvents="none"
        >
          <ImageGenerationField paused={!working} animation={animation} />
        </Animated.View>

        {resolution ? <Text className={slots.resolution()}>{resolution}</Text> : null}
      </View>

      {showStatus ? (
        <View
          accessibilityLiveRegion="polite"
          className={slots.status({ className: statusClassName })}
        >
          <StatusMark status={status} />
          <Text className={slots.statusText()}>{sentence}</Text>
        </View>
      ) : null}

      {prompt ? (
        <Text numberOfLines={1} className={slots.prompt()}>
          {prompt}
        </Text>
      ) : null}

      {status === 'error' && onRetry ? (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel="Try again"
          onPress={onRetry}
          className={slots.retry()}
        >
          <RotateCcwIcon size={16} />
          <Text className={slots.retryLabel()}>Try again</Text>
        </Pressable>
      ) : null}
    </View>
  );
}

ImageGenerationRoot.displayName = 'ImageGeneration';
ImageGenerationField.displayName = 'ImageGeneration.Field';

export const ImageGeneration = Object.assign(ImageGenerationRoot, {
  Field: ImageGenerationField,
});
